From 0d9916e6f11f0fd3b714c8590db1a55d0bf51bd3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:48:18 +0100
Subject: [PATCH] containments/desktop: add Reset Rotation button and Shift
 snapping
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

A widget rotated by accident could only be brought back with a precise
drag on the rotate handle. Add a Reset Rotation button to the handle of
rotated widgets, and snap the angle to 15° steps while Shift is held.

BUG: 517492
---
 .../package/contents/ui/ConfigOverlay.qml     | 24 +++++++++++++++----
 1 file changed, 19 insertions(+), 5 deletions(-)

diff --git a/containments/desktop/package/contents/ui/ConfigOverlay.qml b/containments/desktop/package/contents/ui/ConfigOverlay.qml
index 5e028670f9..75fbac13ef 100644
--- a/containments/desktop/package/contents/ui/ConfigOverlay.qml
+++ b/containments/desktop/package/contents/ui/ConfigOverlay.qml
@@ -94,7 +94,7 @@ ContainmentLayoutManager.ConfigOverlayWithHandles {
             ActionButton {
                 id: rotateButton
                 icon.name: "object-rotate-left-symbolic"
-                toolTip: !rotateHandle.pressed ? i18nc("@action:button tooltip rotate widget", "Click and drag to rotate") : ""
+                toolTip: !rotateHandle.pressed ? i18nc("@action:button tooltip rotate widget", "Click and drag to rotate, hold Shift to snap to 15° steps") : ""
                 action: applet ? applet.plasmoid.internalAction("rotate") : null
                 down: rotateHandle.pressed
                 Component.onCompleted: {
@@ -146,10 +146,14 @@ ContainmentLayoutManager.ConfigOverlayWithHandles {
                             newRotation = newRotation % 360;
                         }

-                        snapIt(0);
-                        snapIt(90);
-                        snapIt(180);
-                        snapIt(270);
+                        if (mouse.modifiers & Qt.ShiftModifier) {
+                            newRotation = Math.round(newRotation / 15) * 15 % 360;
+                        } else {
+                            snapIt(0);
+                            snapIt(90);
+                            snapIt(180);
+                            snapIt(270);
+                        }

                         function snapIt(snapTo) {
                             if (newRotation > (snapTo - snap) && newRotation < (snapTo + snap)) {
@@ -167,6 +171,16 @@ ContainmentLayoutManager.ConfigOverlayWithHandles {
                 }
             }

+            ActionButton {
+                icon.name: "edit-reset-symbolic"
+                toolTip: i18nc("@action:button tooltip", "Reset Rotation")
+                visible: overlay.itemContainer.rotation !== 0
+                onClicked: {
+                    overlay.itemContainer.rotation = 0;
+                    overlay.itemContainer.layout.save();
+                }
+            }
+
             ActionButton {
                 icon.name: "configure"
                 visible: qAction && qAction.enabled && (applet && applet.plasmoid.hasConfigurationInterface)
-- 
2.53.0
